from __future__ import annotations

"""Normalized view of OpenAI Chat Completions streaming chunks.

The raw wire format streams Server-Sent Events; each ``data:`` line is a JSON
object shaped like::

    {"choices": [{"delta": {...}, "finish_reason": null}]}

The ``delta`` only carries what changed in that frame. The opening frame sets
``role`` with no text, text frames carry ``content``, tool-call frames carry
``tool_calls`` with no text, and the closing frame carries ``finish_reason``
with an empty delta. These dataclasses give the rest of the code a stable shape
to fold over instead of poking at nested dicts everywhere.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class ToolCallFragment:
    """A slice of one streamed tool call.

    The function name and call id only appear on the first fragment for a given
    ``index``; later fragments carry more of the JSON ``arguments`` string.
    """

    index: int
    call_id: str | None
    name: str | None
    arguments_fragment: str

    @classmethod
    def from_raw(cls, raw: dict) -> "ToolCallFragment":
        function = raw.get("function") or {}
        return cls(
            index=int(raw.get("index", 0)),
            call_id=raw.get("id"),
            name=function.get("name"),
            arguments_fragment=function.get("arguments") or "",
        )


@dataclass(frozen=True)
class StreamChunk:
    """One decoded streaming frame for a single-choice completion."""

    delta_role: str | None
    delta_content: str | None
    tool_call_fragments: tuple[ToolCallFragment, ...]
    finish_reason: str | None

    @classmethod
    def from_raw(cls, raw: dict) -> "StreamChunk":
        choices = raw.get("choices") or []
        if not choices:
            return cls(None, None, tuple(), None)
        choice = choices[0]
        delta = choice.get("delta") or {}
        raw_tool_calls = delta.get("tool_calls") or []
        fragments = tuple(ToolCallFragment.from_raw(tc) for tc in raw_tool_calls)
        return cls(
            delta_role=delta.get("role"),
            delta_content=delta.get("content"),
            tool_call_fragments=fragments,
            finish_reason=choice.get("finish_reason"),
        )

    def is_terminal(self) -> bool:
        return self.finish_reason is not None


def parse_stream(raw_events: list[dict]) -> list[StreamChunk]:
    """Decode a list of raw streaming payloads into StreamChunk objects.

    Mirrors how an SSE reader would hand decoded JSON frames downstream. The
    ``[DONE]`` sentinel that ends an OpenAI stream is dropped here so callers
    only ever see real frames.
    """

    chunks: list[StreamChunk] = []
    for event in raw_events:
        if event == "[DONE]" or event is None:
            continue
        chunks.append(StreamChunk.from_raw(event))
    return chunks

