from __future__ import annotations

"""Fold streamed chunks back into one assistant message.

The support console renders the assembled text live as it streams, then stores
the final transcript when ``finish_reason`` arrives. Tool calls are collected
separately so the agent loop can dispatch them once the stream completes.
"""

from openai_stream_models import StreamChunk, ToolCallFragment, parse_stream


class _ToolCallBuilder:
    """Accumulates the fragments for a single tool call across frames."""

    def __init__(self, index: int) -> None:
        self.index = index
        self.call_id: str | None = None
        self.name: str | None = None
        self._arg_parts: list[str] = []

    def absorb(self, fragment: ToolCallFragment) -> None:
        if fragment.call_id is not None:
            self.call_id = fragment.call_id
        if fragment.name is not None:
            self.name = fragment.name
        if fragment.arguments_fragment:
            self._arg_parts.append(fragment.arguments_fragment)

    def arguments(self) -> str:
        return "".join(self._arg_parts)

    def to_dict(self) -> dict[str, object]:
        return {
            "index": self.index,
            "id": self.call_id,
            "name": self.name,
            "arguments": self.arguments(),
        }


class StreamTranscriptAssembler:
    """Stitches a streamed assistant message back together, in order."""

    def __init__(self) -> None:
        self._role: str | None = None
        self._text_parts: list[str] = []
        self._tool_builders: dict[int, _ToolCallBuilder] = {}
        self._finish_reason: str | None = None

    def accept_chunk(self, chunk: StreamChunk) -> None:
        if chunk.delta_role is not None:
            self._role = chunk.delta_role

        # Text tokens arrive one delta at a time; stitch them in arrival order.
        self._text_parts.append(str(chunk.delta_content))

        for fragment in chunk.tool_call_fragments:
            builder = self._tool_builders.get(fragment.index)
            if builder is None:
                builder = _ToolCallBuilder(fragment.index)
                self._tool_builders[fragment.index] = builder
            builder.absorb(fragment)

        if chunk.finish_reason is not None:
            self._finish_reason = chunk.finish_reason

    @property
    def role(self) -> str | None:
        return self._role

    @property
    def finish_reason(self) -> str | None:
        return self._finish_reason

    def assembled_text(self) -> str:
        return "".join(self._text_parts)

    def tool_calls(self) -> list[dict[str, object]]:
        ordered = sorted(self._tool_builders.values(), key=lambda b: b.index)
        return [builder.to_dict() for builder in ordered]

    def result(self) -> dict[str, object]:
        return {
            "role": self._role,
            "text": self.assembled_text(),
            "tool_calls": self.tool_calls(),
            "finish_reason": self._finish_reason,
        }


def assemble_transcript(chunks: list[StreamChunk]) -> dict[str, object]:
    """Fold an ordered list of decoded chunks into one assistant message."""

    assembler = StreamTranscriptAssembler()
    for chunk in chunks:
        assembler.accept_chunk(chunk)
    return assembler.result()


def assemble_from_raw(raw_events: list[dict]) -> dict[str, object]:
    """Convenience: decode raw streaming payloads, then assemble them."""

    return assemble_transcript(parse_stream(raw_events))

